1	// Motion-liveness head-turn challenge (Gate Scanner + V-Patrol).
2	//
3	// The old check compared one absolute single-frame ratio against fixed bands
4	// (e.g. ratio < 0.35 || ratio > 0.65), which stays stuck for anyone whose
5	// resting pose already sits mid-band. This module instead measures CHANGE from
6	// the person's own baseline pose using the lightweight tracking samples:
7	//
8	//   1. Baseline = median of up to three recent valid tracking ratios.
9	//   2. delta = currentRatio - baselineRatio.
10	//   3. Pass when |delta| >= LIVENESS_MOVEMENT_THRESHOLD for
11	//      LIVENESS_CONSECUTIVE_SAMPLES consecutive tracking samples.
12	//   4. Time out (fail closed) after LIVENESS_TIMEOUT_MS.
13	//
14	// This is motion liveness / head-turn verification — NOT full presentation-
15	// attack detection, and it never grants access by itself: the caller must run
16	// a final full recognition and require the same matched user ID.
17	
18	export const LIVENESS_MOVEMENT_THRESHOLD = 0.08;
19	export const LIVENESS_CONSECUTIVE_SAMPLES = 2;
20	export const LIVENESS_TIMEOUT_MS = 15000;
21	export const LIVENESS_BASELINE_SAMPLES = 3;
22	
23	export const CHALLENGE_STATE = {
24	  COLLECTING_BASELINE: 'COLLECTING_BASELINE',
25	  PENDING: 'PENDING',
26	  PASSED: 'PASSED',
27	  TIMED_OUT: 'TIMED_OUT',
28	};
29	
30	/** True for a finite numeric head-turn ratio (nullish/NaN samples are invalid). */
31	export const isValidRatio = (ratio) =>
32	  typeof ratio === 'number' && Number.isFinite(ratio);
33	
34	/** Median of a non-empty numeric array. */
35	export const median = (values) => {
36	  const sorted = [...values].sort((a, b) => a - b);
37	  const mid = Math.floor(sorted.length / 2);
38	  return sorted.length % 2 === 1 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
39	};
40	
41	/**
42	 * Create one head-turn challenge. `initialSamples` should be the recent valid
43	 * tracking ratios observed just before the candidate was recognised (up to
44	 * three are used); if none are available yet, the challenge collects its
45	 * baseline from the first valid samples it observes.
46	 *
47	 * observe(ratio, now) -> { state, baseline, delta, consecutive }
48	 * Callers must pass `ratio ?? null` — never a fake default like `ratio || 0.5`.
49	 */
50	export function createHeadTurnChallenge({
51	  movementThreshold = LIVENESS_MOVEMENT_THRESHOLD,
52	  requiredConsecutiveSamples = LIVENESS_CONSECUTIVE_SAMPLES,
53	  timeoutMs = LIVENESS_TIMEOUT_MS,
54	  baselineSampleTarget = LIVENESS_BASELINE_SAMPLES,
55	  initialSamples = [],
56	  startedAt = Date.now(),
57	} = {}) {
58	  const baselineSamples = initialSamples.filter(isValidRatio).slice(-baselineSampleTarget);
59	  let baseline = baselineSamples.length > 0 ? median(baselineSamples) : null;
60	  let consecutive = 0;
61	
62	  return {
63	    get baseline() { return baseline; },
64	    get consecutive() { return consecutive; },
65	    requiredConsecutiveSamples,
66	
67	    observe(ratio, now = Date.now()) {
68	      if (now - startedAt >= timeoutMs) {
69	        return { state: CHALLENGE_STATE.TIMED_OUT, baseline, delta: null, consecutive };
70	      }
71	
72	      const current = isValidRatio(ratio) ? ratio : null;
73	
74	      if (baseline === null) {
75	        if (current !== null) {
76	          baselineSamples.push(current);
77	          if (baselineSamples.length >= baselineSampleTarget) {
78	            baseline = median(baselineSamples);
79	          }
80	        }
81	        return { state: CHALLENGE_STATE.COLLECTING_BASELINE, baseline, delta: null, consecutive };
82	      }
83	
84	      if (current === null) {
85	        // Face lost / no keypoints this sample — movement streak resets.
86	        consecutive = 0;
87	        return { state: CHALLENGE_STATE.PENDING, baseline, delta: null, consecutive };
88	      }
89	
90	      const delta = current - baseline;
91	      if (Math.abs(delta) >= movementThreshold) {
92	        consecutive += 1;
93	      } else {
94	        consecutive = 0; // tiny jitter never accumulates toward a pass
95	      }
96	
97	      return {
98	        state: consecutive >= requiredConsecutiveSamples
99	          ? CHALLENGE_STATE.PASSED
100	          : CHALLENGE_STATE.PENDING,
101	        baseline,
102	        delta,
103	        consecutive,
104	      };
105	    },
106	  };
107	}
