1	// Face-box coordinate contract (Gate Scanner + V-Patrol).
2	//
3	// FastAPI returns exactly `box = [x, y, width, height]` in pixels of the
4	// CAPTURED frame (the hidden canvas the snapshot was drawn onto). There is no
5	// other format — the frontend maps it directly and never guesses corner
6	// orderings.
7	//
8	// The preview element (`.video-feed`) renders the camera with
9	// `object-fit: contain`, so the frame is letterboxed inside the container.
10	// These helpers clamp the box to the frame and project it into container
11	// pixel coordinates, accounting for the contain (or cover) scaling + offsets
12	// so the overlay lines up with the face on screen.
13	
14	/** Clamp [x, y, width, height] so the box never leaves the frame bounds. */
15	export function clampBoxToFrame(box, frameWidth, frameHeight) {
16	  const [rawX, rawY, rawW, rawH] = box.map(Number);
17	  const x = Math.min(Math.max(rawX || 0, 0), frameWidth);
18	  const y = Math.min(Math.max(rawY || 0, 0), frameHeight);
19	  const width = Math.min(Math.max(rawW || 0, 0), frameWidth - x);
20	  const height = Math.min(Math.max(rawH || 0, 0), frameHeight - y);
21	  return { x, y, width, height };
22	}
23	
24	/**
25	 * Project a frame-space box into container pixel coordinates for an element
26	 * displayed with object-fit. `fit` is 'contain' (letterboxed, default) or
27	 * 'cover' (cropped). Returns null when either rect has no size yet.
28	 */
29	export function mapBoxToContainer(box, frame, container, fit = 'contain') {
30	  if (!frame?.width || !frame?.height || !container?.width || !container?.height) return null;
31	  const { x, y, width, height } = clampBoxToFrame(box, frame.width, frame.height);
32	
33	  const scale = fit === 'cover'
34	    ? Math.max(container.width / frame.width, container.height / frame.height)
35	    : Math.min(container.width / frame.width, container.height / frame.height);
36	  const offsetX = (container.width - frame.width * scale) / 2;
37	  const offsetY = (container.height - frame.height * scale) / 2;
38	
39	  return {
40	    left: offsetX + x * scale,
41	    top: offsetY + y * scale,
42	    width: width * scale,
43	    height: height * scale,
44	  };
45	}
46	
47	// Box smoothing: blend the previous frame-space box with the newest tracking
48	// box so the overlay follows the face without jitter. 0.55/0.45 keeps latency
49	// low (over-smoothing would make the box visibly lag the person).
50	export const BOX_SMOOTHING_PREV_WEIGHT = 0.55;
51	
52	/**
53	 * Blend two frame-space boxes ({x, y, width, height}). Returns the current box
54	 * unchanged when there is no previous box to smooth against.
55	 */
56	export function smoothBox(previous, current, prevWeight = BOX_SMOOTHING_PREV_WEIGHT) {
57	  if (!current) return null;
58	  if (!previous) return current;
59	  const currentWeight = 1 - prevWeight;
60	  return {
61	    x: previous.x * prevWeight + current.x * currentWeight,
62	    y: previous.y * prevWeight + current.y * currentWeight,
63	    width: previous.width * prevWeight + current.width * currentWeight,
64	    height: previous.height * prevWeight + current.height * currentWeight,
65	  };
66	}
67	
68	/** Same projection, as a ready-to-spread CSS style ({left/top/width/height} px). */
69	export function faceBoxStyle(box, frame, container, fit = 'contain') {
70	  const rect = mapBoxToContainer(box, frame, container, fit);
71	  if (!rect) return null;
72	  return {
73	    left: `${rect.left}px`,
74	    top: `${rect.top}px`,
75	    width: `${rect.width}px`,
76	    height: `${rect.height}px`,
77	  };
78	}
