1	// Presentation helper for recognition results returned by the Node backend
2	// (POST /api/facial-recognition/recognize). Works only with safe fields —
3	// id, name, role, status, confidence — never biometric template data.
4	
5	export const RECOGNITION_STATUS = {
6	  AUTHORIZED: 'AUTHORIZED',
7	  SUSPENDED: 'SUSPENDED',
8	  DENIED: 'DENIED',
9	};
10	
11	// Returns UI strings for a recognition subject: who they are (name, role,
12	// confidence) and the access outcome (granted / suspended / unknown).
13	export const describeRecognitionSubject = (user) => {
14	  if (!user || user.id == null) {
15	    return {
16	      identityLabel: 'Unknown Person',
17	      accessLabel: 'ACCESS DENIED — SUSPICIOUS PERSON',
18	      granted: false,
19	    };
20	  }
21	
22	  const confidencePct = Math.round((user.confidence || 0) * 100);
23	  const identityLabel = `${user.name} • ${user.role} • ${confidencePct}% match`;
24	
25	  if (user.status === RECOGNITION_STATUS.SUSPENDED) {
26	    return {
27	      identityLabel,
28	      accessLabel: 'ACCESS DENIED — ACCOUNT SUSPENDED',
29	      granted: false,
30	    };
31	  }
32	
33	  return {
34	    identityLabel,
35	    accessLabel: 'ACCESS GRANTED',
36	    granted: user.status === RECOGNITION_STATUS.AUTHORIZED,
37	  };
38	};
