1	// Raspberry Pi Camera Module 3 — gate camera node configuration.
2	// URLs come from Vite env (VITE_PI_CAMERA_STREAM_URL / VITE_PI_CAMERA_SNAPSHOT_URL).
3	//
4	// The out-of-the-box fallback exists ONLY in local development (mDNS hostname,
5	// never a private IP). A production/cloud build ships NO default Pi address:
6	// unless VITE_PI_CAMERA_* is explicitly configured (kiosk builds on the demo
7	// network), the Pi is treated as unreachable and every scanner page falls back
8	// to the browser webcam. SecurePi alert ingestion is unaffected — the Pi
9	// pushes outbound to the authenticated /api/edge route; the cloud never
10	// reaches into the LAN.
11	const DEV_PI_BASE = import.meta.env.DEV ? "http://raspberrypi.local:8081" : "";
12	
13	export const PI_CAMERA_STREAM_URL =
14	  import.meta.env.VITE_PI_CAMERA_STREAM_URL || (DEV_PI_BASE ? `${DEV_PI_BASE}/video_feed` : "");
15	
16	export const PI_CAMERA_SNAPSHOT_URL =
17	  import.meta.env.VITE_PI_CAMERA_SNAPSHOT_URL || (DEV_PI_BASE ? `${DEV_PI_BASE}/snapshot` : "");
18	
19	export const CAMERA_SOURCES = {
20	  PI: "pi",
21	  WEBCAM: "webcam",
22	};
23	
24	export const CAMERA_STATUS_MESSAGES = {
25	  PI_CONNECTED: "Pi Gate Camera connected",
26	  PI_UNAVAILABLE: "Pi Camera unavailable — using laptop webcam fallback",
27	  WEBCAM_ACTIVE: "Laptop webcam active",
28	};
29	
30	// While the Pi is known-unavailable, don't re-probe it on every recognition
31	// cycle — cache the failure and only allow a fresh probe after this cooldown.
32	// Laptop-webcam recognition is never blocked by a pending Pi timeout.
33	export const PI_UNAVAILABLE_COOLDOWN_MS = 10000;
34	
35	let piUnavailableUntil = 0;
36	
37	/** Record a Pi failure so probes are throttled for the cooldown window. */
38	export function markPiUnavailable(now = Date.now()) {
39	  piUnavailableUntil = now + PI_UNAVAILABLE_COOLDOWN_MS;
40	}
41	
42	/** True while a recent Pi failure is cached (probing would be wasted time). */
43	export function isPiInCooldown(now = Date.now()) {
44	  return now < piUnavailableUntil;
45	}
46	
47	/** Clear the cached Pi failure (tests / explicit user retry). */
48	export function resetPiAvailabilityCache() {
49	  piUnavailableUntil = 0;
50	}
51	
52	/**
53	 * Cooldown-aware reachability check: while a recent Pi failure is cached,
54	 * returns false immediately WITHOUT a network probe, so scanner pages fall
55	 * back to the laptop webcam fast instead of waiting out a Pi timeout.
56	 */
57	export async function isPiCameraReachableCached(now = Date.now()) {
58	  if (isPiInCooldown(now)) return false;
59	  const reachable = await isPiCameraReachable();
60	  if (!reachable) markPiUnavailable();
61	  else piUnavailableUntil = 0;
62	  return reachable;
63	}
64	
65	/**
66	 * Probe the Pi snapshot endpoint to decide if the gate camera is reachable.
67	 * Any network error, CORS block, or timeout counts as unreachable so the
68	 * caller can fall back to the laptop webcam.
69	 */
70	export async function isPiCameraReachable(timeoutMs = 3500) {
71	  // No Pi camera configured (e.g. any cloud build without VITE_PI_CAMERA_*):
72	  // report unreachable immediately so pages use the browser webcam.
73	  if (!PI_CAMERA_SNAPSHOT_URL) return false;
74	  try {
75	    const controller = new AbortController();
76	    const timer = setTimeout(() => controller.abort(), timeoutMs);
77	    const res = await fetch(`${PI_CAMERA_SNAPSHOT_URL}?probe=${Date.now()}`, {
78	      cache: "no-store",
79	      signal: controller.signal,
80	    });
81	    clearTimeout(timer);
82	    return res.ok;
83	  } catch {
84	    return false;
85	  }
86	}
87	
88	/**
89	 * Fetch one frame from the Pi snapshot endpoint as an ImageBitmap that can be
90	 * drawn onto the existing capture canvas (blob-backed, so the canvas is not
91	 * tainted and toDataURL keeps working for the recognition API).
92	 */
93	export async function fetchPiSnapshotBitmap(timeoutMs = 4000) {
94	  if (!PI_CAMERA_SNAPSHOT_URL) throw new Error("Pi camera is not configured.");
95	  const controller = new AbortController();
96	  const timer = setTimeout(() => controller.abort(), timeoutMs);
97	  try {
98	    const res = await fetch(`${PI_CAMERA_SNAPSHOT_URL}?t=${Date.now()}`, {
99	      cache: "no-store",
100	      signal: controller.signal,
101	    });
102	    if (!res.ok) throw new Error(`Pi snapshot HTTP ${res.status}`);
103	    const blob = await res.blob();
104	    return await createImageBitmap(blob);
105	  } finally {
106	    clearTimeout(timer);
107	  }
108	}
