1	// Recognition scan tuning + control for Gate Scanner / V-Patrol.
2	// Performance-tuned WITHOUT weakening security: liveness verification, the
3	// no-overlap guard, and Pi snapshot fallback logic all stay in place.
4	
5	// Scan cadence (was 1200 ms) and target-lock delay (was 1800 ms).
6	export const SCAN_INTERVAL_MS = 1000;
7	export const TARGET_LOCK_MS = 600;
8	
9	// Recognition frames need enough facial detail for stable embeddings on
10	// Cloud Run CPU inference. 512 px is still lightweight, but avoids the
11	// over-compression/low-detail mismatch that can produce very weak similarities.
12	export const CAPTURE_MAX_WIDTH = 512;
13	
14	// Keep embedding-grade detail without sending full-quality webcam frames.
15	export const CAPTURE_JPEG_QUALITY = 0.74;
16	
17	// --- Lightweight tracking loop (face box + head-turn sampling) --------------
18	// Independent of the full recognition loop: it calls the detection-only
19	// /api/facial-recognition/track endpoint, which returns no identity data.
20	
21	// Tracking cadence — fast enough for a live-feeling box, slow enough to keep
22	// one request in flight at a time on CPU-only detection.
23	export const TRACK_INTERVAL_MS = 250;
24	
25	// Tracking frames are small + heavily compressed: the detector only needs
26	// coarse geometry, not embedding-grade image quality.
27	export const TRACK_MAX_WIDTH = 256;
28	export const TRACK_JPEG_QUALITY = 0.5;
29	
30	// The box survives one brief missed detection, then clears after this long
31	// without a face so a stale box never hovers over an empty frame.
32	export const BOX_CLEAR_TIMEOUT_MS = 800;
33	
34	// When Node/FastAPI is unreachable, pause scanning briefly instead of flooding
35	// the endpoint every second. The camera preview keeps running.
36	export const AI_ERROR_BACKOFF_MS = 5000;
37	
38	export const SERVICE_UNAVAILABLE_MSG = 'Recognition service unavailable — retrying shortly…';
39	
40	/**
41	 * Scan gate: enforces the no-overlapping-request guard and the AI-error
42	 * retry backoff. One instance per scanner page (kept in a ref).
43	 */
44	export const createScanGate = () => {
45	  let busy = false;
46	  let backoffUntil = 0;
47	
48	  return {
49	    /** True when a new scan may start (not busy, not backing off). */
50	    canScan(now = Date.now()) {
51	      return !busy && now >= backoffUntil;
52	    },
53	    begin() { busy = true; },
54	    end() { busy = false; },
55	    /** Pause scanning after a recognition-service failure. */
56	    applyBackoff(ms = AI_ERROR_BACKOFF_MS, now = Date.now()) {
57	      backoffUntil = now + ms;
58	    },
59	    clearBackoff() { backoffUntil = 0; },
60	    isBackingOff(now = Date.now()) {
61	      return now < backoffUntil;
62	    },
63	  };
64	};
65	
66	/** Wall-clock milliseconds (kept out of component bodies for hook purity). */
67	export const nowMs = () => Date.now();
68	
69	/** Millisecond stopwatch: `const t = startTimer(); ... const ms = t();` */
70	export const startTimer = () => {
71	  const startedAt = Date.now();
72	  return () => Date.now() - startedAt;
73	};
74	
75	/**
76	 * Dev-only timing telemetry. Logs durations ONLY — never images, frames,
77	 * or biometric data. No-op in production builds.
78	 */
79	export const logScanTimings = ({ captureMs, apiMs, totalMs, serverTimings }) => {
80	  if (!import.meta.env.DEV) return;
81	  const parts = [
82	    captureMs != null ? `capture(Pi/webcam) ${captureMs}ms` : null,
83	    apiMs != null ? `frontend→Node ${apiMs}ms` : null,
84	    serverTimings?.nodeToAiMs != null ? `Node→FastAPI ${serverTimings.nodeToAiMs}ms` : null,
85	    serverTimings?.inferenceMs != null ? `inference ${serverTimings.inferenceMs}ms` : null,
86	    totalMs != null ? `total ${totalMs}ms` : null,
87	  ].filter(Boolean);
88	  console.debug(`[recognition timing] ${parts.join(' | ')}`);
89	};
90	
91	/**
92	 * Dev-only tracking-loop telemetry: capture/request/detector durations ONLY —
93	 * never images, frames, or biometric data. No-op in production builds.
94	 */
95	export const logTrackingTimings = ({ captureMs, requestMs, inferenceMs }) => {
96	  if (!import.meta.env.DEV) return;
97	  const parts = [
98	    captureMs != null ? `capture ${captureMs}ms` : null,
99	    requestMs != null ? `request ${requestMs}ms` : null,
100	    inferenceMs != null ? `detector ${inferenceMs}ms` : null,
101	  ].filter(Boolean);
102	  console.debug(`[tracking timing] ${parts.join(' | ')}`);
103	};
104	
105	/**
106	 * Dev-only head-turn liveness telemetry: baseline/current/delta ratios and the
107	 * consecutive-valid-sample count ONLY — never images or biometric templates.
108	 */
109	export const logLivenessTelemetry = ({ baseline, current, delta, consecutive }) => {
110	  if (!import.meta.env.DEV) return;
111	  const fmt = (v) => (typeof v === 'number' ? v.toFixed(3) : 'n/a');
112	  console.debug(
113	    `[liveness] baseline ${fmt(baseline)} | current ${fmt(current)} | delta ${fmt(delta)} | consecutive ${consecutive ?? 0}`
114	  );
115	};
