1	// Frontend tests — FM-only Loading Bay Gate Verification page.
2	// Camera, QR and OCR are mocked at the util boundary so no physical camera is
3	// needed; axios is mocked so no server is hit.
4	import React from "react";
5	import { render, screen, fireEvent, waitFor, act, cleanup } from "@testing-library/react";
6	import { MemoryRouter } from "react-router-dom";
7	import { vi, describe, test, expect, beforeEach, afterEach } from "vitest";
8	
9	const h = vi.hoisted(() => {
10	  const store = { onResult: null, onError: null };
11	  const qrStop = vi.fn();
12	  const plateStop = vi.fn();
13	  return {
14	    store, qrStop, plateStop,
15	    startQrScan: vi.fn(async ({ onResult, onError }) => { store.onResult = onResult; store.onError = onError; return qrStop; }),
16	    startCamera: vi.fn(async () => ({ stop: plateStop })),
17	    recognizePlate: vi.fn(async () => ({ raw: "gbg 1234 m", normalized: "GBG1234M", confidence: 88 })),
18	    post: vi.fn(),
19	  };
20	});
21	
22	vi.mock("axios", () => ({ default: { post: h.post } }));
23	vi.mock("../../src/components/Sidebar", () => ({ default: () => <div data-testid="sidebar" /> }));
24	vi.mock("../../src/utils/plateOcr", () => ({ recognizePlate: h.recognizePlate }));
25	vi.mock("../../src/utils/gateCamera", async (importOriginal) => {
26	  const actual = await importOriginal();
27	  return {
28	    ...actual,
29	    startQrScan: h.startQrScan,
30	    startCamera: h.startCamera,
31	    isSecureCameraContext: () => true,
32	    isCameraSupported: () => true,
33	  };
34	});
35	
36	import GateVerification from "../../src/pages/GateVerification";
37	
38	const renderPage = (role = "FM") => {
39	  localStorage.setItem("accessToken", "test-token");
40	  localStorage.setItem("userRole", role);
41	  return render(<MemoryRouter><GateVerification /></MemoryRouter>);
42	};
43	
44	const clickStartQr = async () => {
45	  await act(async () => { fireEvent.click(screen.getByRole("button", { name: /Start QR Scanner/i })); });
46	};
47	
48	beforeEach(() => {
49	  vi.clearAllMocks();
50	  localStorage.clear();
51	  sessionStorage.clear();
52	  h.store.onResult = null;
53	  h.store.onError = null;
54	  h.post.mockResolvedValue({ data: {} });
55	});
56	
57	afterEach(cleanup);
58	
59	describe("Access control", () => {
60	  test("1. Non-FM roles see a restricted message, FM sees the tool", () => {
61	    renderPage("Tenant");
62	    expect(screen.getByText(/restricted to Facilities Managers/i)).toBeTruthy();
63	    cleanup();
64	    renderPage("FM");
65	    expect(screen.getByRole("tab", { name: /Automatic Verification/i })).toBeTruthy();
66	  });
67	});
68	
69	describe("Camera lifecycle", () => {
70	  test("2. camera does NOT start automatically on load", () => {
71	    renderPage();
72	    expect(h.startQrScan).not.toHaveBeenCalled();
73	    expect(h.startCamera).not.toHaveBeenCalled();
74	  });
75	
76	  test("3. QR scanner starts only after the button is pressed", async () => {
77	    renderPage();
78	    expect(h.startQrScan).not.toHaveBeenCalled();
79	    await clickStartQr();
80	    expect(h.startQrScan).toHaveBeenCalledTimes(1);
81	  });
82	
83	  test("6. camera tracks are released on Stop and on unmount", async () => {
84	    const { unmount } = renderPage();
85	    await clickStartQr();
86	    fireEvent.click(screen.getByRole("button", { name: /Stop Scanner/i }));
87	    expect(h.qrStop).toHaveBeenCalled();
88	
89	    // And again if the page unmounts while scanning.
90	    h.qrStop.mockClear();
91	    await clickStartQr();
92	    unmount();
93	    expect(h.qrStop).toHaveBeenCalled();
94	  });
95	
96	  test("7. a permission failure surfaces a message and manual mode stays available", async () => {
97	    h.startQrScan.mockImplementationOnce(async ({ onError }) => {
98	      onError({ code: "permission", message: "Camera permission was denied. Allow camera access or switch to manual verification." });
99	      return h.qrStop;
100	    });
101	    renderPage();
102	    await clickStartQr();
103	    expect(await screen.findByText(/permission was denied/i)).toBeTruthy();
104	    expect(screen.getByRole("tab", { name: /Manual Verification/i })).toBeTruthy();
105	  });
106	});
107	
108	describe("QR result handling", () => {
109	  test("4. a valid FlowGuard QR fills the booking reference", async () => {
110	    renderPage();
