1	// Browser camera + QR helpers for the Gate Verification page.
2	//
3	// All camera access is user-initiated (the page only calls these after the FM
4	// presses a button) and every start returns a stop() that releases the camera
5	// tracks. @zxing/browser is loaded via dynamic import so it stays out of the
6	// initial app bundle. QR frames are never stored — decoding is live-only.
7	
8	// FlowGuard booking references look like "FG-XXXXXX" (genRef → FG + 6 hex chars).
9	// Accept FG- followed by 4–12 alphanumerics; reject arbitrary QR text.
10	const BOOKING_REF_RE = /^FG-[A-Z0-9]{4,12}$/;
11	
12	export function normalizeBookingRef(raw) {
13	  return String(raw ?? '').trim().toUpperCase();
14	}
15	
16	export function isValidBookingRef(raw) {
17	  return BOOKING_REF_RE.test(normalizeBookingRef(raw));
18	}
19	
20	// getUserMedia requires a secure context (HTTPS) — localhost is treated as secure.
21	export function isSecureCameraContext() {
22	  if (typeof window === 'undefined') return false;
23	  if (window.isSecureContext === true) return true;
24	  const host = window.location?.hostname || '';
25	  return host === 'localhost' || host === '127.0.0.1';
26	}
27	
28	export function isCameraSupported() {
29	  return typeof navigator !== 'undefined'
30	    && !!navigator.mediaDevices
31	    && typeof navigator.mediaDevices.getUserMedia === 'function';
32	}
33	
34	const FRIENDLY = {
35	  insecure: 'Camera requires a secure (HTTPS) connection. Use HTTPS or localhost, or switch to manual verification.',
36	  unsupported: 'This browser does not support camera access. Please use a modern browser or manual verification.',
37	  permission: 'Camera permission was denied. Allow camera access or switch to manual verification.',
38	  'no-camera': 'No camera was found on this device. Please use manual verification.',
39	  unknown: 'The camera could not be started. Please try again or use manual verification.',
40	};
41	
42	export function cameraErrorMessage(code) {
43	  return FRIENDLY[code] || FRIENDLY.unknown;
44	}
45	
46	function makeError(code) {
47	  const err = new Error(cameraErrorMessage(code));
48	  err.code = code;
49	  return err;
50	}
51	
52	function mapGetUserMediaError(e) {
53	  const name = e?.name || '';
54	  if (name === 'NotAllowedError' || name === 'PermissionDeniedError' || name === 'SecurityError') return makeError('permission');
55	  if (name === 'NotFoundError' || name === 'DevicesNotFoundError' || name === 'OverconstrainedError') return makeError('no-camera');
56	  return makeError('unknown');
57	}
58	
59	function stopTracks(videoElement, stream) {
60	  const src = stream || videoElement?.srcObject;
61	  if (src && typeof src.getTracks === 'function') {
62	    src.getTracks().forEach((t) => { try { t.stop(); } catch { /* ignore */ } });
63	  }
64	  if (videoElement) {
65	    try { videoElement.srcObject = null; } catch { /* ignore */ }
66	  }
67	}
68	
69	// Prefer the rear/environment camera; fall back to any camera.
70	const REAR_CONSTRAINTS = { video: { facingMode: { ideal: 'environment' } }, audio: false };
71	
72	// Start a plain live-preview camera (used by the PoC plate-capture step).
73	// Throws a coded Error (code: insecure | unsupported | permission | no-camera | unknown).
74	export async function startCamera(videoElement) {
75	  if (!isSecureCameraContext()) throw makeError('insecure');
76	  if (!isCameraSupported()) throw makeError('unsupported');
77	  let stream;
78	  try {
79	    stream = await navigator.mediaDevices.getUserMedia(REAR_CONSTRAINTS);
80	  } catch (e) {
81	    throw mapGetUserMediaError(e);
82	  }
83	  if (videoElement) {
84	    videoElement.srcObject = stream;
85	    try { await videoElement.play?.(); } catch { /* autoplay quirks are non-fatal */ }
86	  }
87	  return { stop: () => stopTracks(videoElement, stream) };
88	}
89	
90	// Start live QR decoding on a <video>. Calls onResult(text) on a decode and
91	// onError({ code, message }) on a start failure. Returns a stop() function that
92	// releases the camera. Per-frame "not found" scans are ignored (normal).
93	export async function startQrScan({ videoElement, onResult, onError }) {
94	  if (!isSecureCameraContext()) { onError?.({ code: 'insecure', message: cameraErrorMessage('insecure') }); return () => {}; }
95	  if (!isCameraSupported()) { onError?.({ code: 'unsupported', message: cameraErrorMessage('unsupported') }); return () => {}; }
96	
97	  let controls;
98	  let stopped = false;
99	  try {
100	    const { BrowserQRCodeReader } = await import('@zxing/browser');
101	    const reader = new BrowserQRCodeReader();
102	    controls = await reader.decodeFromConstraints(REAR_CONSTRAINTS, videoElement, (result) => {
103	      if (stopped || !result) return;
104	      const text = typeof result.getText === 'function' ? result.getText() : String(result.text ?? result);
105	      onResult?.(text);
106	    });
107	  } catch (e) {
108	    const mapped = mapGetUserMediaError(e);
109	    onError?.({ code: mapped.code, message: mapped.message });
110	    return () => {};
111	  }
112	
113	  return () => {
114	    stopped = true;
115	    try { controls?.stop(); } catch { /* ignore */ }
116	    stopTracks(videoElement);
117	  };
118	}
