1	// Proof-of-Concept plate OCR wrapper.
2	//
3	// tesseract.js is loaded via DYNAMIC import so the (large) OCR/WASM code is only
4	// downloaded when the FM actually runs recognition — it never bloats the initial
5	// app bundle. The image is processed in memory and discarded by the caller; this
6	// module never persists frames or uploads them anywhere.
7	//
8	// This is a PoC, NOT production-grade licence-plate recognition. Accuracy varies
9	// with lighting, glare, angle and plate condition — manual verification remains
10	// available in the UI.
11	
12	import { normalizePlate } from './plate';
13	
14	// Draw a source image/video/canvas onto an offscreen canvas with light
15	// preprocessing (grayscale + contrast) to give OCR a cleaner signal. Optionally
16	// crop to a normalised guide rectangle {x,y,w,h} in 0–1 units.
17	export function preprocessToCanvas(source, { crop } = {}) {
18	  const srcW = source.videoWidth || source.naturalWidth || source.width;
19	  const srcH = source.videoHeight || source.naturalHeight || source.height;
20	  if (!srcW || !srcH) throw new Error('The captured image was empty. Please retake.');
21	
22	  const sx = crop ? Math.round(crop.x * srcW) : 0;
23	  const sy = crop ? Math.round(crop.y * srcH) : 0;
24	  const sw = crop ? Math.round(crop.w * srcW) : srcW;
25	  const sh = crop ? Math.round(crop.h * srcH) : srcH;
26	
27	  const canvas = document.createElement('canvas');
28	  canvas.width = sw;
29	  canvas.height = sh;
30	  const ctx = canvas.getContext('2d');
31	  ctx.drawImage(source, sx, sy, sw, sh, 0, 0, sw, sh);
32	
33	  // Grayscale + simple contrast stretch. Wrapped in try/catch because some test
34	  // environments (jsdom) do not implement getImageData.
35	  try {
36	    const img = ctx.getImageData(0, 0, sw, sh);
37	    const d = img.data;
38	    const contrast = 1.4;
39	    const intercept = 128 * (1 - contrast);
40	    for (let i = 0; i < d.length; i += 4) {
41	      let g = 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
42	      g = g * contrast + intercept;
43	      g = g < 0 ? 0 : g > 255 ? 255 : g;
44	      d[i] = d[i + 1] = d[i + 2] = g;
45	    }
46	    ctx.putImageData(img, 0, 0);
47	  } catch { /* preprocessing is best-effort */ }
48	
49	  return canvas;
50	}
51	
52	// Run OCR on an image source (canvas/image/video/blob URL). Returns
53	// { raw, normalized, confidence }. Throws on OCR failure.
54	export async function recognizePlate(source, { crop } = {}) {
55	  const input = (typeof HTMLCanvasElement !== 'undefined' && source instanceof HTMLCanvasElement)
56	    ? source
57	    : preprocessToCanvas(source, { crop });
58	
59	  const mod = await import('tesseract.js');
60	  const recognize = mod.recognize || mod.default?.recognize || mod.default;
61	  const result = await recognize(input, 'eng');
62	  const data = result?.data || {};
63	  const raw = String(data.text || '').trim();
64	  const confidence = typeof data.confidence === 'number' ? Math.round(data.confidence * 10) / 10 : null;
65	
66	  return { raw, normalized: normalizePlate(raw), confidence };
67	}
